    {
      "id": "g14",
      "unit": 6,
      "title": "Questions and Negatives in the Simple Past (did/didn't) & Emphatic Intensifiers (so vs. such)",
      "summary": "To form questions and negative statements in the Simple Past with main verbs, use the auxiliary 'did' / 'didn't' followed strictly by the BASE FORM of the verb (never the past form). To add descriptive emphasis, use 'so' before standalone adjectives (so exciting, so ancient) and 'such a / such' before noun phrases (such an amazing exhibition, such beautiful calligraphy).",
      "formula": "Past Negative: Subject + didn't + BASE VERB (He didn't go / She didn't buy)\nPast Question: Did + Subject + BASE VERB? (Did you see the exhibit?)\nWh- Question: Wh- Word + did + Subject + BASE VERB? (What did they see?)\nIntensifier 'So': so + Adjective (The museum was SO fascinating)\nIntensifier 'Such': such a(n) + Adjective + Singular Noun (It was SUCH AN inspiring visit)",
      "comparisonTable": [
        {
          "Form": "Past Negative Statement",
          "Formula": "Subject + didn't + Base Verb",
          "CorrectExample": "We didn't visit the modern gallery.",
          "CommonPitfall": "Avoid: *We didn't visited (auxiliary absorbs past tense)"
        },
        {
          "Form": "Yes/No Past Question",
          "Formula": "Did + Subject + Base Verb?",
          "CorrectExample": "Did you admire the Thuluth script?",
          "CommonPitfall": "Avoid: *Did you admired (base verb is mandatory)"
        },
        {
          "Form": "Wh- Information Question",
          "Formula": "Wh- + did + Subject + Base Verb?",
          "CorrectExample": "Where did they unearth the ancient artifact?",
          "CommonPitfall": "Avoid: *Where did they unearthed?"
        },
        {
          "Form": "Intensifier with 'So'",
          "Formula": "so + Adjective / Adverb",
          "CorrectExample": "The historical fortress was SO impressive.",
          "CommonPitfall": "Use before adjectives without a subsequent noun"
        },
        {
          "Form": "Intensifier with 'Such'",
          "Formula": "such + (a/an) + Adjective + Noun",
          "CorrectExample": "It was SUCH A memorable school trip.",
          "CommonPitfall": "Requires an accompanying modified noun"
        }
      ],
      "commonErrors": [
        {
          "incorrect": "Did you saw the Saudi national flag in the exhibition hall?",
          "correct": "Did you see the Saudi national flag in the exhibition hall?",
          "explanation": "When the auxiliary 'did' is used in questions, the main verb must revert to its uninflected base form ('see'), not the past form ('saw').",
          "visualClue": "⚠️ Auxiliary 'Did' + Base Verb Rule"
        },
        {
          "incorrect": "We didn't bought any tickets because admission was free.",
          "correct": "We didn't buy any tickets because admission was free.",
          "explanation": "The negative auxiliary 'didn't' already marks the past tense; the lexical verb following it must be in the base form ('buy').",
          "visualClue": "⚠️ Negative 'Didn't' + Base Verb Rule"
        },
        {
          "incorrect": "It was so amazing museum that we stayed until closing time.",
          "correct": "It was such an amazing museum that we stayed until closing time.",
          "explanation": "When modifying an adjective that precedes a noun ('amazing museum'), use 'such an', not 'so'. 'So' directly modifies standalone adjectives.",
          "visualClue": "⚠️ 'So' vs 'Such' Syntax Distinction"
        }
      ],
      "diagnosticQuestions": [
        {
          "question": "'What ______ in the Islamic civilization pavilion?' — 'We saw rare Qur'anic manuscripts.'",
          "options": [
            "did you see",
            "did you saw",
            "were you see",
            "did you seen"
          ],
          "correctAnswer": 0,
          "explanation": "Information questions in the Simple Past require the auxiliary 'did' followed by the subject and the base verb 'see'.",
          "visualClue": "🔍 Past Question Auxiliary Syntax"
        },
        {
          "question": "Fahd enjoyed the archaeological exhibition, but he ______ have time to tour the aerospace pavilion.",
          "options": [
            "didn't",
            "wasn't",
            "doesn't",
            "haven't"
          ],
          "correctAnswer": 0,
          "explanation": "The past negative auxiliary for main action verbs like 'have' is 'didn't'.",
          "visualClue": "⏳ Time Constraint Negative Syntax"
        },
        {
          "question": "The ancient rock inscriptions in Al-Ula were ______ magnificent that historians traveled from around the world to study them.",
          "options": [
            "so",
            "such",
            "too",
            "enough"
          ],
          "correctAnswer": 0,
          "explanation": "'So' directly modifies the standalone predicate adjective 'magnificent' before the result clause 'that...'.",
          "visualClue": "🌄 Archaeological Monument Magnificence"
        },
        {
          "question": "Our guided visit to historical Diriyah was ______ an extraordinary experience that we wrote a long report about it.",
          "options": [
            "such",
            "so",
            "very",
            "too"
          ],
          "correctAnswer": 0,
          "explanation": "Before a modified noun phrase ('an extraordinary experience'), the intensifier 'such' is grammatically mandatory.",
          "visualClue": "🏰 Historical Expedition Report"
        }
      ]
    }
