      "unit": 1,
      "title": "The Place to Stay",
      "subtitle": "Youth Hostels and the S.A.Y.H.A. Network Across Saudi Arabia",
      "passage": "Many young people traveling around the world are backpackers or students on a low budget. They want to see the world, but they cannot afford to pay for regular luxury hotels. So youth hostels are the perfect solution for travelers without a lot of money to spend. Today there are more than 4,000 hostels in over 80 countries, and the Saudi Arabian Youth Hostels Association (S.A.Y.H.A.) offers comfortable accommodations in 21 cities across the Kingdom.\n\nThe accommodations in hostels are inexpensive because guests usually share rooms and bathrooms. Most hostels have a laundry room, telephones, Internet connection, and a restaurant. Some hostels also offer cooking facilities, such as a kitchen with pots and dishes. Youth hostels are usually located in interesting places where young people can learn about local monuments, history, and culture. Some hostels are even inside old historic buildings, castles, and on boats!\n\nHostels are definitely the place for socializing. The guests, who are from different cities or countries, have the opportunity to meet other young people and share experiences. Many hostels organize tours and fun activities. For example, S.A.Y.H.A. holds sports and painting competitions, and there are also prizes for the best community projects. So when traveling, youth hostels are the best place to stay, explore, and make new lifelong friends.",
