      "subtitle": "The Digital Video Revolution in Modern Education",
      "passage": "Watching videos on the Web is fun, but did you know that videos are also good for learning? Today, videos are more than just entertainment; they are rapidly becoming popular tools for e-learning. Many teachers today show web videos in their classrooms. What better way to help students understand geography or science! And there are thousands of video clips to choose from—you can witness active volcanoes erupting, explore the latest developments in technology, or learn more about global environmental protection.\n\nFor some students and teachers, the Web has literally become their classroom. More and more students are taking online lessons. Some language students, for example, learn on their own from educational websites, and others connect with their teacher online with the help of a webcam. There are also established online schools like the Khan Academy with over 3,000 video lessons in math, science, economics, and history—and it is absolutely free!\n\nDo you want to know how to bake a delicious cheesecake or learn how to play golf? Free how-to videos online can teach you. Anyone can e-learn, and it is easy!",
