      "title": "Jobs and Employment in Saudi Arabia",
      "subtitle": "Human Capital Development, Economic Diversification & Saudi Vision 2030 Employment Goals",
      "passage": "Saudi Arabia has many assets. We have many advantages — our place, our society, our economy and our people. We will use these to build the best future for our country.\n\nOur vision is built around three themes: A good society, a strong economy and a determined nation.\n\nA strong economy needs people to have good jobs and to work hard. We started a 'Job Creation Team' to help people find jobs. We assist new businesses that give people jobs and training. We improve technology and digital systems to support businesses and we give training and advice to people who are looking for jobs. We improved the education system to fit with the jobs that the economy needs.\n\nHalf of the people in Saudi Arabia are under the age of 25. This is a huge asset to our country and economy. We support young people in finding jobs they enjoy and that help the economy and society. We build and support a culture of determination and achieving goals.\n\nAmong our goals by 2030: To lower the rate of unemployment from 11.6% to 7%. To increase women's participation in the workforce from 22% to 30%. Adapted from the text of the Vision Programs at vision2030.gov.sa and the Council of Economic and Development Affairs.",
