      "title": "Sky HIGH! Aeromodelling & Drone Aviation",
      "subtitle": "Radio-Controlled Aircraft, Jet Propulsion & High-Tech Aviation Hobbies",
      "passage": "Aeromodelling is an exciting hobby. It attracts people of all ages. They all have one common interest — the love of flying small-sized airplanes. Most people no longer fly the old elastic-propelled planes. They no longer fly planes that are attached to two cables and that fly in circles around them. Nowadays, with the advances in technology, the big thing is radio-controlled airplanes. These models fly like real aircraft and are an aeromodeller's ultimate dream. People control the movement of the planes through radio signals. Aeromodels can even perform aerobatics in the sky!\n\nRadio-controlled airplanes come in all shapes and sizes: from the Mini Flyer-plane with a wingspan of 9 inches (23 centimeters), to the huge passenger jet models with a 29 1/2-foot (9-meter) wingspan. The price of the airplanes varies from $30 to several thousand dollars. There are different methods of propulsion, or ways to power the planes. These range from electric motors to expensive jet turbines.\n\nJet-powered models are sophisticated aircraft. Their engines sound like those of full-size jet planes. These jet models can travel at speeds of 236 miles (380 kilometers) per hour — that's more than the top speed of a Formula 1 race car.\n\nJet models always attract large crowds at aeromodelling competitions. At these competitions, fliers usually do a series of actions with their planes, including launchings, landings, and doing maneuvers in the air. Aeromodelling is a popular hobby all over the world. In the United States, for example, the Academy of Model Aeronautics has more than 170,000 members in 250 model airplane clubs. The organization advertises the great things about aeromodelling as a sport.",
