      "subtitle": "International Restaurant Chains, Cultural Adaptations & Global Middle Eastern Cuisines",
      "passage": "International fast-food chains are becoming more and more popular everywhere! You can have burgers, sandwiches, pizza, ice cream, coffee, and soft drinks in restaurants in the Americas, Europe, and Asia. In general, pizza in New York tastes more or less like a pizza in Italy or Hong Kong. However, there are some changes in the food according to the tastes and culture of the different countries. For example, in Japan, you can get a shrimp burger at McDonald's, and in KSA, the McArabia sandwich with chicken or beef is very popular.\n\nSome famous brands had difficulty when they first entered certain countries. For example, in Peru, the most popular soft drink was and still is Inca Kola. Coca Cola couldn't compete against Inca Kola, so they bought the factory. Now they produce Coca Cola and Inca Kola. In China, people usually drink tea, but coffee is becoming more and more popular. There are about 4,800 Starbucks coffee shops in the country.\n\nIn the past, most ethnic foods were just local. Nowadays with globalization, ethnic foods are also becoming popular everywhere. Pizza is originally from Italy, but today there are over 78,000 pizzerias in the U.S., and the number is growing. Asian food is found in food courts everywhere. And one of the most popular Middle Eastern foods around the world is shawarma, which is sometimes also called doner.",
