      "id": "r6",
      "unit": 6,
      "title": "Art of the Pen: Arabic Calligraphy",
      "subtitle": "The Sacred Origins, Six Classical Styles & UNESCO Living Heritage of Islamic Penmanship",
      "passage": "The word calligraphy means 'beautiful writing.' Arabic calligraphy has beautiful lines and shapes. But the true beauty of calligraphy is that it is used to write the holy words of the Qur'an. That is how and why the art of Arabic calligraphy started.\n\nThe first Arabic system of writing (script) was very simple. Then, with the spread of Islam, there was a need for a more expressive form of writing to communicate Allah's words in the Holy Qur'an. It was important to have a clear script that all the people of Islam could easily read and understand.\n\nToday, there are six main styles of Arabic calligraphy. One of the oldest styles is Kufic script. It has straight, geometric letters that make it easy to cut into wood or stone. This is the script calligraphers used to write the first copies of the Holy Qur'an.\n\nThe other main styles are cursive and have connecting letters. Thuluth is a long and elegant script that is often used to write the headings of surahs, Holy Qur'anic chapters. It is also the script of the Saudi Arabian flag. Naskh and Ruq'ah are popular scripts that are common in printing and handwriting. They are generally smaller and easier to read and write. Farsi or Ta'liq, which means 'hanging,' is an old script that is sometimes used in literature. Diwani is a very decorative style that is often seen on greeting cards.\n\nThis summer, the Islamic Heritage Museum is proud to present a special exhibit called Art of the Pen: Arabic Calligraphy. Admire the beautiful art of Arabic calligraphy and Holy Qur'anic verse. Learn about the history of calligraphy and its development.",
      "keyVocab": [
        "calligraphy",
        "Holy Qur'an",
        "Kufic script",
        "Thuluth",
        "Naskh",
        "Ruq'ah",
        "Diwani",
        "Islamic Heritage Museum"
      ],
