        "unit": 2,
        "title": "Describing How the Internet Is a Useful Tool for Students",
        "prompt": "Write a cohesive paragraph (80–120 words) explaining why the Internet is an essential and valuable learning tool for modern students. Support your main claims with specific examples using the targeted connectors: such as, like, for example, for instance, especially, and because.",
        "guidelines": [
          "Begin with a strong topic sentence stating the educational value of the Internet.",
          "Provide at least three distinct supporting details (e.g., e-learning platforms, online reference dictionaries, interactive videos).",
          "Skillfully embed linking words: 'such as', 'like', 'for example', 'for instance', 'especially', and 'because'.",
          "Conclude with an impactful summarizing thought about autonomous digital learning."
        ],
        "modelText": "The Internet is an indispensable educational tool that transforms modern learning into an engaging, interactive experience for students. First, students do not have to spend hours searching through heavy library books because they possess a vast digital database at home. For instance, learners can access instant reference resources, such as online encyclopedias, interactive dictionaries, and digital thesauruses. Furthermore, multimedia websites make complex scientific concepts simple and memorable; for example, learners can watch high-definition video clips of erupting volcanoes or deep-sea ecosystems. Online academies like Khan Academy are especially helpful for self-paced revision in mathematics and history. In conclusion, the Internet empowers students to acquire knowledge anywhere and anytime with unprecedented speed.",
